/** Render measured losses, unavailable evidence and the exact registered denominator. */
import type { Report, PlaceScaleReceipt } from './place-report.types.ts';
export function renderPlaceReport(r: Report, receipt: PlaceScaleReceipt): string {
  if (r.index.receiptSha256 !== receipt.sha256) throw Error('place renderer received another scale receipt');
  const c = r.coverage, f = r.floor;
  return ['# Sourced place conformance', '',
    'Generated by `npm run benchmark:place -- --json benchmark/results/place.json --md docs/PLACE_BENCHMARK.md`.', '',
    `Fixture: \`${r.fixtureHash}\`. Report: \`${r.sha256}\`. Effective source: \`${r.source.sha256}\`.`, '',
    `Corpus: **${r.corpus.status}**${r.corpus.detail ? ` — ${r.corpus.detail}` : ''}. ${r.census.questions} original questions; ${r.census.turns} source turns audited.`, '',
    '## Scope and source qualification', '',
    'No number here is a LoCoMo score. These are original host-asserted annotations of named places in the separately licensed conversation corpus. The location and movement questions address an explicit reporting-session annotation index, not the historical time of a trip. Source observations retain minute precision; exact query points identify the supplied reporting index. The one residence with an unknown end remains unknown.', '',
    'Coordinates are verbatim sourced Wikidata CC0 point proxies. Rounded distances use the native spherical IUGG mean-radius model, in metres, between those proxies. They do not measure traveled routes, exact persona positions, or ellipsoidal distance. Nearby and cell-boundary questions concern gazetteer geometry alone.', '',
    '| Audited mentions | Grounded | Ungrounded | Ambiguous | Grounded fraction | Personas with positions | Position assertions |',
    '|---:|---:|---:|---:|---:|---:|---:|',
    `| ${c.mentionSites} | ${c.grounded} | ${c.ungrounded} | ${c.ambiguous} | ${(c.grounded / c.mentionSites).toFixed(6)} | ${c.personas} | ${c.positions} |`, '',
    '| Admission condition | Registered threshold | Observed |', '|---|---:|---:|',
    `| Grounded fraction | ≥ ${f.minimumGroundedFraction} | ${f.groundedFraction} |`,
    `| Conversations with location questions | ≥ ${f.minimumLocationConversations} | ${f.locationConversations} |`,
    `| Conversations with movement questions | ≥ ${f.minimumMovementConversations} | ${f.movementConversations} |`,
    `| Unsourced entries | ≤ ${f.maximumUnsourcedEntries} | ${f.unsourcedEntries} |`, '',
    '## Equal-budget methods', '',
    `Hash embedding dimensions ${r.registration.dims}; candidate pool ${r.registration.candidatePool}; final k ${r.registration.k}; minimum score ${r.registration.minScore}. All comparable rows share one projection per conversation and a source-occurrence-id ordering for score ties. The full finite source pool precedes eligibility. Hash embeddings measure lexical retrieval mechanics, not live embedding quality.`, '',
    'The oracle reads privileged audited annotations and native geometry/time kernels; it never reads the question expectations. The seeded control draws one uniformly selected entry for every question, including kinds that cannot be answered by one entry. Ordinary retrieval chooses the first grounded mention among its top-k turns. The temporal baseline receives the event session instant from the instrument because it cannot join two series. Both baselines record no-geometry on distance/proximity questions. Temporal unknown-validity and no-match losses are retained.', '',
    'The place method reads complete subject-qualified position series, joins reporting events backward with the native as-of kernel, and then checks the matched claim’s validity. A later exact reporting point can establish a position after an earlier unknown-ended state; an unknown-time assertion, an expired match or an uncertain event still refuses. All event and position citations must fit the same semantic pool and final k. Mention questions call the source-span matcher with the independently audited locative qualification; they do not turn mention status or expected answers into runtime refusals.', '',
    'The three registered place backends retain independent rows from memory and actual Node/Bun SQLite execution. Nearby probes validate nine contiguous native cells before distance refinement, exclude the centre entry, and refuse radii they cannot cover. An absent runtime or corpus is never a passing zero. Exactness uses the complete registered per-kind denominator; correct refusals are scored by the same exact equality as answers.', '',
    '| Method | Backend | Kind | Planned | Measured | Passed | Incorrect | Failed | Missing | Unavailable | Exactness |',
    '|---|---|---|---:|---:|---:|---:|---:|---:|---:|---:|',
    ...r.summaries.map(s => `| ${s.row} | ${s.backend} | ${s.kind} | ${s.counts.planned} | ${s.counts.measured} | ${s.counts.passed} | ${s.counts.incorrect} | ${s.counts.failed} | ${s.counts.implementationMissing} | ${s.counts.unavailable} | ${s.exactness === null ? 'unmeasured' : s.exactness.toFixed(6)} |`), '',
    '## Runtime evidence coverage', '',
    'These are sums of per-question read counts, including refused questions; repeated reads of one position are counted repeatedly. They are not a second census of unique source assertions. Unplaceable counts unaccepted assertions and time kinds other than state/point; an accepted state with an unknown end instead refuses when its exact validity is queried. Complete asserts that a finalized recall used all comparable sources without pool truncation; it does not turn an uncertain position into an answer. Source geometry questions need no persona claims or invented citations.', '',
    '| Backend | Questions with coverage | Source occurrences | Comparable | Semantic candidates | Position rows | Unplaceable rows | Truncated pools | Complete coverage |',
    '|---|---:|---:|---:|---:|---:|---:|---:|---:|',
    ...(['memory', 'node-sqlite', 'bun-sqlite'] as const).map(backend => {
      const coverage = r.rows.filter(row => row.row === 'meaning-time-place' && row.backend === backend).flatMap(row => row.runtimeCoverage ? [row.runtimeCoverage] : []);
      const sum = (field: 'occurrences' | 'comparable' | 'semanticCandidates' | 'positions' | 'unplaceable') => coverage.reduce((n, c) => n + c[field], 0);
      return `| ${backend} | ${coverage.length} | ${sum('occurrences')} | ${sum('comparable')} | ${sum('semanticCandidates')} | ${sum('positions')} | ${sum('unplaceable')} | ${coverage.filter(c => c.poolTruncated).length} | ${coverage.filter(c => c.complete).length} |`;
    }), '',
    `Seed ${r.registration.seed}: ${r.randomFloor.passed} control successes; analytic expected successes ${r.randomFloor.expectedPasses.toFixed(6)}, preregistered band [${r.randomFloor.lowerPasses.toFixed(6)}, ${r.randomFloor.upperPasses.toFixed(6)}] (four standard deviations plus one-question slack). Band holds: ${r.randomFloor.holds}.`, '',
    '## Refusals and scorer controls', '',
    '| Spatial fixture | Expected | Observed | Passed |', '|---|---|---|---|',
    ...r.gateFixtures.map(g => `| ${g.path} | ${g.expectedCode} | ${g.actualCode ?? 'none'} | ${g.passed} |`), '',
    `Counterfeit answers rejected: ${r.wrongControls.filter(c => c.rejected).length}/${r.wrongControls.length}. Unmatched position joins: ${r.refusals.unmatchedJoins}.`, '',
    '| Refusal code | Count |', '|---|---:|', ...Object.entries(r.refusals.byCode).sort().map(([code, n]) => `| ${code} | ${n} |`), '',
    '| Underlying cause, including the exercised prefix gate | Count |', '|---|---:|', ...Object.entries(r.refusals.byCause).sort().map(([code, n]) => `| ${code} | ${n} |`), '',
    '## Ablation under equal budgets', '',
    `All pairs use the memory backend, embedding \`${r.ablation.embeddedBy.model}\` (${r.ablation.embeddedBy.dims} dimensions), candidate pool ${r.ablation.candidatePool}, final k ${r.ablation.k}, minimum score ${r.ablation.minScore}, and the same ${r.ablation.projectionIds.length} captured projection versions. The independently measured SQLite rows above remain separate backend qualification.`, '',
    'A win means the left method is correct and the right is incorrect; a loss means the reverse. Ties include both-correct and both-incorrect answers. Wins + losses + ties = paired questions; unavailable or failed pairs remain unpaired. Refusals on either side are overlapping subsets, including correct refusals, and are never added again to the denominator. With tens of questions per kind, no paired interval is claimed.', '',
    'Structural means a baseline could not answer because it has no geometry. Those rows establish added capability, not measured quality improvement. Temporal eligibility losses, including unknown-validity refusals, remain alongside its wins.', '',
    '| Left | Right | Kind | Comparison | Questions | Paired | Unpaired | Wins | Losses | Ties | Refused left | Refused right |',
    '|---|---|---|---|---:|---:|---:|---:|---:|---:|---:|---:|',
    ...r.ablation.pairs.map(p => `| ${p.left} | ${p.right} | ${p.kind} | ${p.comparison} | ${p.questions} | ${p.paired} | ${p.unpaired} | ${p.wins} | ${p.losses} | ${p.ties} | ${p.refusedLeft} | ${p.refusedRight} |`), '',
    '## Registered candidate scale decision', '',
    `Separate timing receipt: [place-scale.json](../benchmark/receipts/place-scale.json), SHA-256 \`${receipt.sha256}\`; measurement source \`${receipt.source.sha256}\`. The canonical conformance JSON binds this receipt and decision without copying observed timings. Run \`npm run benchmark:place:scale -- --check\` to verify it without sampling a clock.`, '',
    `Registered ${receipt.registration.entries} entries, ${receipt.registration.probes} probes, ${receipt.registration.warmups} warmups, seed ${receipt.registration.seed}, precision ${receipt.registration.precision}, radius ${receipt.registration.radiusMetres} metres. ${receipt.registration.distribution}. Decision: **${receipt.decision}**; target met: **${receipt.targetMet}**, against **${receipt.registration.targetP95Ms} ms** warm p95 on every measured runtime. Bbox is tried only after the sweep fails; R-tree requires a failing bbox and the native capability.`, '',
    '| Runtime | Shape | Used prefilter | Cold p50 ms | Cold p95 ms | Warm p50 ms | Warm p95 ms | Warm candidate sum | Warm refined sum | Status |',
    '|---|---|---|---:|---:|---:|---:|---:|---:|---|',
    ...receipt.runtimes.flatMap(runtime => (['sweep', 'bbox', 'rtree'] as const).map(shape => {
      const row = runtime.rows[shape];
      return row ? `| ${runtime.runtime} ${runtime.version} | ${shape} | ${row.via} | ${row.cold.p50Ms.toFixed(3)} | ${row.cold.p95Ms.toFixed(3)} | ${row.warm.p50Ms.toFixed(3)} | ${row.warm.p95Ms.toFixed(3)} | ${row.warm.samples.reduce((n, s) => n + s.candidates, 0)} | ${row.warm.samples.reduce((n, s) => n + s.refined, 0)} | measured |`
        : `| ${runtime.runtime}${runtime.version ? ` ${runtime.version}` : ''} | ${shape} | — | — | — | — | — | — | — | not-run: ${runtime.notRun[shape]} |`;
    })), '',
    receipt.limits, '',
    'Each cold sample is followed by an untimed exact-sweep verification and native distance/hash checks. The warm pass follows that first pass and the registered warmups. Candidate sums include the centre entry; refined sums exclude it.', '',
    ...(receipt.runtimes.filter(runtime => runtime.status === 'measured').every(runtime => runtime.rows.sweep!.warm.samples.every(sample => sample.candidates === 1 && sample.refined === 0))
      ? ['In this sparse registered sample, every probe contains only its centre and returns no neighbour within the radius.', ''] : []),
    '## Non-regression and limits', '',
    `Canonical recall SHA-256: \`${r.locomo.recallSha256}\`. Canonical QA SHA-256: \`${r.locomo.qaSha256}\`. These reports remain unchanged; this instrument does not relabel category 1–4 results.`, '',
    `Physical live requests: ${r.liveRequests}. The configuration envelope honestly records no executed provider stack; this is separate from a measured keyless row. Default routing stays **${r.default}**. Live extraction and model quality are unmeasured. Timing is excluded from this canonical report; the registered ${r.scale.entries}-entry/${r.scale.probes}-probe scale experiment has a ${r.scale.targetP95Ms} ms warm p95 target.`, '',
  ].join('\n');
}
